// Curated, real mind maps to show on the landing page.
//
// Every one of these was generated by the live YouTube flow
// (POST /yt/transform on the api worker), then hand-picked. The full source is
// committed next to this file rather than fetched from the API at render time,
// for three reasons: the landing page must not depend on the API being up to
// draw itself, `robots.txt` disallows /svg so a crawler would never see an
// API-served thumbnail, and a source in the repo is reviewable in a PR before
// it goes public.
//
// `shareId` is the 11-char content hash under which the api worker stored the
// same payload, so the card can link to the canonical /s/<id> page. It is NOT
// how the preview is drawn.
//
// Adding one: generate a map, save its source as `<slug>.mmd` here (ASCII only
// -- the model emits curly quotes and non-breaking hyphens, normalise them),
// then add an entry below. `pnpm --filter @mindmaply/editor test` checks that
// every source parses and that ids and slugs are well formed.

import jobsSource from './steve-jobs-stanford-2005.mmd?raw'
import roslingSource from './hans-rosling-best-stats.mmd?raw'
import mcravenSource from './mcraven-make-your-bed.mmd?raw'
import pauschSource from './randy-pausch-last-lecture.mmd?raw'
import { SHARE_BASE } from '../share'

export interface Example {
  /** URL-safe id. Reserved for the prerendered /examples/<slug>/ pages. */
  slug: string
  /** Human title. Shorter than the YouTube title, which is often unwieldy. */
  title: string
  /** One sentence. Doubles as the meta description on the per-example page. */
  blurb: string
  /** 11-char content-hash id stored by the api worker (see /shorten). */
  shareId: string
  /** Source video, credited on the card. */
  videoId: string
  /** The full generated map. */
  source: string
}

