/**
 * Root plus first-level branches only.
 *
 * These maps are 66 to 74 lines and render about 1500x4300, an aspect around
 * 0.35. Fitted whole into a card that is wider than it is tall, the labels come
 * out a few pixels high and the card reads as texture rather than as a diagram.
 * Trimming to depth 1 leaves 6 to 9 nodes at an aspect of 0.96 to 1.73, which
 * is card-shaped and legible. Same trick, and the same reason, as
 * MOBILE_DEMO_SOURCE in Landing.tsx.
 *
 * The card links to the full map; this only governs the thumbnail.
 */
export function previewSource(source: string): string {
  return source
    .split('\n')
    .filter((line) => line.startsWith('# ') || line.startsWith('- '))
    .join('\n')
}

/**
 * Canonical share page for an example, or null when no share base is
 * configured (a local dev build without VITE_SHARE_BASE, or a fork). Built from
 * SHARE_BASE rather than a literal domain so forks and zone config win, exactly
 * as shortenShareUrl does.
 *
 * `view=map` matches the links the Chrome extension hands out: the editor opens
 * with the source panel collapsed, map first.
 */
export function exampleShareUrl(example: Example): string | null {
  if (!SHARE_BASE) return null
  return `${SHARE_BASE}s/${example.shareId}?view=map`
}

/** The talk this map was generated from. */
export function exampleVideoUrl(example: Example): string {
  return `https://www.youtube.com/watch?v=${example.videoId}`
}
